        const result = await api.call.dryRunApi.dryRunXcm(origin, message);

        console.log(
          'Dry run XCM result:',
          JSON.stringify(result.toJSON(), null, 2)
        );

        await api.disconnect();
        console.log('Disconnected from the API.');
      } catch (error)
    };

    main().catch(console.error);
    ```

